-- Site texts administration: moves the public links that were constants of the web client into the
-- existing profile row (an empty list only, so a replay keeps edited links), creates the legal notice
-- and the privacy policy from the static pages they replace (same text, dated 2 November 2026; an
-- existing row is kept), then queues one site rebuild for a database that already holds published
-- content, so that the site is rebuilt from the new snapshot once this service runs. A fresh database
-- has no revision row: the seed writes its content and its revision.
UPDATE content.profile SET links = '[{"kind":"email","url":"mailto:contact@valentin-fortin.pro","label":null},{"kind":"github","url":"https://github.com/DevSkyLex","label":null},{"kind":"linkedin","url":"https://www.linkedin.com/in/valentin-fortin","label":null}]'::jsonb WHERE id = 1 AND links = '[]'::jsonb;
