WITH bumped AS (
  UPDATE content.content_revision SET revision = revision + 1 WHERE id = 1 RETURNING revision
)
INSERT INTO content.site_build_requests (revision, status, attempts, requested_at, next_attempt_at)
SELECT revision, 'pending', 0, now(), now() FROM bumped;
